- Reader component (full file, web/src/pages/Reader.tsx lines 1-21):
  import { useEffect, useState } from "react";
  import MemoContent from "@/components/MemoContent";
  import { loadMemos, selectMemos } from "@/lib/reader";
  import { Memo } from "@/types/proto/api/v1/memo_service";
  import "@/css/reader.css";
  export default function Reader() {
    const [memos, setMemos] = useState<Memo[]>([]);
    const [error, setError] = useState("");
    useEffect(() => { loadMemos().then(setMemos).catch(() => setError("Memos unavailable")); }, []);
    const params = new URLSearchParams(location.search);
    const visible = selectMemos(memos, params);
    return <main className="memo-reader">
      <header className="reader-toolbar"><h1>Public memo reader</h1><a href="/explore">Open Memos</a></header>
      {error && <p>{error}</p>}
      <section className="reader-feed">{visible.map(memo => <article key={memo.name} data-memo={memo.name}>
        <p className="reader-meta">{memo.creator} · {memo.displayTime?.toISOString()}</p>
        <MemoContent nodes={memo.nodes} readonly />
        <div className="reader-attachments">{memo.resources.map(resource => <a key={resource.name} href={resource.externalLink || `/file/${resource.name}/${resource.filename}`}>{resource.filename}</a>)}</div>
      </article>)}</section>
    </main>;
  }
- Data source and selection, web/src/lib/reader.ts lines 1-8 (full):
  import { Memo } from "@/types/proto/api/v1/memo_service";
  export async function loadMemos(): Promise<Memo[]> {
    const response = await fetch("/api/v1/memos?pageSize=100");
    if (!response.ok) throw new Error("Memos unavailable");
    const data = await response.json();
    return (data.memos || []).map((memo: unknown) => Memo.fromPartial({ ...(memo as Memo), displayTime: (memo as Memo).displayTime ? new Date(String((memo as Memo).displayTime)) : undefined }));
  }
  export function selectMemos(memos: Memo[], _params: URLSearchParams): Memo[] { return memos; }

2. Individual memo card for /reader.
- There is no separate card component for /reader: the card is an inline `<article key={memo.name} data-memo={memo.name}>` inside Reader.tsx. Card wrapper element names/attributes: `article`, `data-memo`, and its child classes `reader-meta`, `reader-attachments`.
- Card styling, web/src/css/reader.css lines 1-3 (full file, no shadow, no background):
  .memo-reader { padding: 24px; }
  .reader-feed { display: grid; gap: 20px; }
  .reader-feed article { padding: 16px; border: 1px solid #bbb; }
- For reference, the normal in-app memo card is `MemoView` (web/src/components/MemoView.tsx), not used on /reader. Its wrapper classes (lines 132-137):
  className={cn(
    "group relative flex flex-col justify-start items-start w-full px-4 py-3 mb-2 gap-2 bg-white dark:bg-zinc-800 rounded-lg border border-white dark:border-zinc-800 hover:border-gray-200 dark:hover:border-zinc-700",
    className,
  )}
- There is no `reader-attachments`, `reader-meta`, or `reader-toolbar` styling in any other CSS file (search confirms only reader.css defines them; the class names exist only in reader.css and Reader.tsx).

